export function parseJSON(text: string) {
  try {
    return JSON.parse(text);
  } catch (e) {
    if (e instanceof SyntaxError) {
      throw new Error(`JSON parse failed: ${e.message}`, { cause: e });
    }
    throw e;
  }
}
```

